import { baseline } from "./config.mjs";
import { buildPlan } from "./engine.mjs";
let config = structuredClone(baseline);
const $ = selector => document.querySelector(selector);
const label = id => id.replaceAll("_", " ").replace(/\b\w/g, c => c.toUpperCase());
function renderControls() {
  $("#mode").innerHTML = Object.keys(config.modes).map(mode => `<option value="${mode}">${label(mode)}</option>`).join("");
  $("#mode").value = config.active_mode;
  $("#capacity").innerHTML = Object.entries(config.capacity).map(([key,value]) => `<label>${label(key)}<input data-capacity="${key}" type="number" min="0" value="${value}"></label>`).join("");
  $("#thresholds").innerHTML = Object.entries(config.thresholds).map(([key,value]) => `<label>${label(key)}<input data-threshold="${key}" type="number" min="0" step="0.1" value="${value}"></label>`).join("");
  renderTasks();
}
function renderTasks() { $("#tasks").innerHTML = config.tasks.map((task,index) => `<div class="task" data-index="${index}"><input data-field="id" aria-label="Task name" value="${task.id}">${["player_impact","low_effort","unblocks_work","rework_risk","relevance"].map(key=>`<input data-signal="${key}" title="${label(key)}" aria-label="${label(key)}" type="number" min="0" max="5" step=".5" value="${task.signals[key]}">`).join("")}<input data-field="readiness" aria-label="Readiness" title="Readiness" type="number" min="0" max="5" step="1" value="${task.readiness}"><button class="remove" aria-label="Remove task">×</button></div>`).join(""); }
function sync() { document.querySelectorAll("[data-capacity]").forEach(el=>config.capacity[el.dataset.capacity]=Number(el.value)); document.querySelectorAll("[data-threshold]").forEach(el=>config.thresholds[el.dataset.threshold]=Number(el.value)); document.querySelectorAll(".task").forEach(row=>{const task=config.tasks[Number(row.dataset.index)]; task.id=row.querySelector('[data-field="id"]').value.trim()||"unnamed_task";task.readiness=Number(row.querySelector('[data-field="readiness"]').value);row.querySelectorAll('[data-signal]').forEach(el=>task.signals[el.dataset.signal]=Number(el.value));}); config.active_mode=$("#mode").value; }
function explanation(task) { const signal=task.signals; const strengths=[["player impact",signal.player_impact],["low implementation effort",signal.low_effort],["unblocks work",signal.unblocks_work],["project relevance",signal.relevance]].filter(([,v])=>v>=4).map(([n])=>n); return strengths.length ? strengths.join(" · ") : "Decision follows the active weights, gates, and capacity"; }
function run() { sync(); const plan=buildPlan(config); $("#plan-title").textContent=`${label(plan.mode)} decision plan`; $("#remaining").innerHTML=`Remaining: ${Object.entries(plan.remaining_capacity).map(([k,v])=>`${label(k)} ${v}`).join(" · ")}`; $("#results").innerHTML=plan.tasks.map(item=>{const original=config.tasks.find(t=>t.id===item.id);const cls=item.verdict.toLowerCase().replaceAll(" ","-");return `<article class="result ${cls}"><span class="badge">${item.verdict}${item.rank?` · RANK ${item.rank}`:""}</span><h3>${label(item.id)}</h3><div class="score">${item.priority_score.toFixed(2)}</div><div class="muted">Priority score</div><p class="explain">${explanation(original)}</p><p class="reason">${item.reason}</p></article>`}).join(""); }
$("#run").addEventListener("click",run); $("#run-demo").addEventListener("click",()=>{document.querySelector("#demo").scrollIntoView();run();}); $("#reset").addEventListener("click",()=>{config=structuredClone(baseline);renderControls();run();}); $("#add-task").addEventListener("click",()=>{config.tasks.push({id:"new_task",signals:{player_impact:3,low_effort:3,unblocks_work:2,rework_risk:1,relevance:3},readiness:4,depends_on:[],needs:{programming:1,music:0,art:0,gameplay:0}});renderTasks();}); $("#tasks").addEventListener("click",event=>{if(event.target.matches(".remove")){config.tasks.splice(Number(event.target.closest(".task").dataset.index),1);renderTasks();}});renderControls();run();
